float pixel(float count, vec2 resolution) {
    return 1.0 / max(resolution.x, resolution.y) * count;
}

// 0->1 to -1->1
vec2 centerUV(vec2 uv) {
    return uv * 2.0 - 1.0;
}

// There is probably a way to define this without the if statements...
vec2 correctUVAspect(vec2 uv, vec2 resolution) {
    if(resolution.x >= resolution.y) {
        uv.x *= resolution.x / resolution.y;
    } else {
        uv.y *= resolution.y / resolution.x;
    }
    return uv;
}

float sdCircle(vec2 position, float radius) {
    return length(position)-radius;
}


const vec3 BORDER_COLOUR = vec3(1.0, 1.0, 1.0);
const vec3 IN_COLOUR     = vec3(0.0, 0.5, 0.6);
const vec3 OUT_COLOUR    = vec3(0.4, 0.8, 0.1);

vec4 scene(vec2 uv, vec2 r)
{
    float radius = (sin(iTime * 2.0) + 1.0) * 0.3 + 0.2;
    float d = sdCircle(uv, radius);

    vec3 c;
    c += step(0.0, d) * IN_COLOUR;
    c += step(d, 0.0) * OUT_COLOUR;
    c *= (cos(d * 3.1415 * 40.0 + (d > 0. ? -iTime : iTime) * 10.) + 1.0) * 0.2 + 0.3;
    c *= min(1.0, abs(d) * 5.0);
    c = mix(BORDER_COLOUR, c, smoothstep(pixel(0.0, r), pixel(10.0, r), abs(d)));

    return vec4(c, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = centerUV(uv);
    uv = correctUVAspect(uv, iResolution.xy);

    uv.x += sin(iTime);

    fragColor = scene(uv, iResolution.xy);
}
